import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.2af478d7.js";const u=JSON.parse('{"title":"Index extension","description":"","frontmatter":{},"headers":[],"relativePath":"index-extension.md","filePath":"index-extension.md"}'),i={name:"index-extension.md"};function d(s,e,r,h,c,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="index-extension" tabindex="-1">Index extension <a class="header-anchor" href="#index-extension" aria-label="Permalink to &quot;Index extension&quot;">​</a></h1><p><code>proteo/drupal-search-api</code> adds a Drupal Search API index to the search and related content that core answers from native collections. It is a separate package, installed next to <code>proteo/drupal-backend</code>, and its documentation lives in its own repository. This page says when to install it and what it changes.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Read <a href="./search-setup">Search setup</a>, especially <a href="./search-setup#core-only-or-with-the-index-extension">Core only or with the index extension</a>.</li><li>Install the extension only when a native limit hurts: term matches beyond <code>search.native_limit</code>, counts that read <code>N+</code>, or a boolean flag that exists only in the index.</li></ul><h2 id="what-it-adds" tabindex="-1">What it adds <a class="header-anchor" href="#what-it-adds" aria-label="Permalink to &quot;What it adds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>With the extension</th></tr></thead><tbody><tr><td>Counts</td><td>Exact, from the index&#39;s <code>meta.count</code>.</td></tr><tr><td>Filter-only search</td><td>Answered from the index in one request.</td></tr><tr><td>Typed term</td><td>Still matched natively, or whole-word <code>index_fulltext</code> from the index per content type.</td></tr><tr><td>Boolean filters</td><td>May name a column that exists only in the index; core refuses such a filter.</td></tr><tr><td>Related content</td><td>One ranked query against the index, with a candidate pool you can tune through <code>RelatedRequest::$extras</code>.</td></tr><tr><td><code>drupal:validate</code></td><td>Index probes: the index path and <code>meta.count</code>, the bundle, every column and sort.</td></tr><tr><td><code>drupal:contract</code></td><td>The Search API modules and the index columns of each content type.</td></tr></tbody></table><h2 id="_1-install" tabindex="-1">1. Install <a class="header-anchor" href="#_1-install" aria-label="Permalink to &quot;1. Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proteo/drupal-search-api</span></span></code></pre></div><p>The service provider is discovered automatically. It wraps the <code>SearchBackend</code> and <code>RelatedStrategy</code> bindings with <code>extend()</code>, so the order of providers does not matter, and it tags its checks and contract lines. Only one extension can rebind <code>SearchBackend</code>.</p><h2 id="_2-describe-the-index" tabindex="-1">2. Describe the index <a class="header-anchor" href="#_2-describe-the-index" aria-label="Permalink to &quot;2. Describe the index&quot;">​</a></h2><p>The extension reads its own file, <code>config/drupal-search-api.php</code>, keyed by your content type keys. The native halves of filters, such as <code>native_path</code>, stay in <code>config/drupal-backend.php</code>.</p><p>Check: <code>php artisan drupal:validate</code> ends with an <code>extensions</code> scope that names the index backend and strategy and reports exact counts and fulltext as <code>yes</code>.</p><h2 id="what-does-not-change" tabindex="-1">What does not change <a class="header-anchor" href="#what-does-not-change" aria-label="Permalink to &quot;What does not change&quot;">​</a></h2><ul><li>The descriptor, the routes, the views and the component props are the same.</li><li>The 60-second search cache and the content generation key apply to index requests too. The index lags Drupal by whatever Search API takes to reindex, so a fresh edit may show later in an index answer than in a native one.</li></ul><h2 id="remove-it" tabindex="-1">Remove it <a class="header-anchor" href="#remove-it" aria-label="Permalink to &quot;Remove it&quot;">​</a></h2><p>Uninstall the package and delete <code>config/drupal-search-api.php</code>. Core returns to native search. A filter that relied on an index-only boolean then fails validation until you give it a <code>native</code> path.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Follow the extension&#39;s own documentation in its repository: install, index setup, configuration reference, behaviour, troubleshooting and upgrading from core 2.x.</li><li>Compare the modes in <a href="./search-setup#core-only-or-with-the-index-extension">Search setup</a>.</li><li>Read the decision in <a href="./adr/0002-search-on-native-collections-with-index-for-flags">ADR 0002</a>.</li></ul>',18)])])}const x=t(i,[["render",d]]);export{u as __pageData,x as default};
